                  </div>
                </div>
              </div>
            </div>
            <div class="system-handle">
              <img
                src="../assets/img/chat-refresh.png"
                class="system-refresh"
                @click="handleRefresh(item)"
              />
              <img
                src="../assets/img/chat-copy.png"
                class="system-refresh"
                @click="handleCopy(item.message)"
              />
              <img
                src="../assets/img/chat-hand.png"
                class="system-refresh"
                :class="{ 'liked': likedMessages.has(item.time) }"
                @click="handleLike(item.time)"
              />
              <img
                src="../assets/img/chat-voice.png"
                class="system-refresh"
                @click="handleVoice(item.message)"
              />
            </div>
          </div>
        </template>

        <!-- loading -->
        <!-- <div class="loading" v-if="load">
          <van-loading size="24px" color="#000">正在分析中...</van-loading>
        </div> -->
        <div class="loading" v-if="load">
          <div class="ai-loader">
            <div class="neural-node"></div>
            <div class="neural-node"></div>
            <div class="neural-node"></div>
            <div class="ai-core"></div>
          </div>
        </div>
      </div>
    </div>
    <!-- 提问 -->
    <div class="record">
      <div v-if="imageUrl" class="preview-area">
        <img :src="imageUrl" class="preview-img" />
      </div>
      
      <van-uploader
        :after-read="onAfterRead"
        :max-count="1"
        v-model="fileList"
        accept="image/*"
        v-show="!imageUrl"
      >
      <div class="left">
          <img src="../assets/img/input-add.png" class="left-img" />
        </div>
        </van-uploader>
     
      <div class="center">
        <textarea
          type="text"
          placeholder="请选择需要质检的图片，或者输入你的问题"
          class="center-input"
          v-model="message"
          @keyup.enter="sendMessage"
        />
        <div class="center-text">
          <div class="center-text-item">
            <img src="../assets/img/icon-tip.png" class="center-tip" />
            <div @click="openTipsList" style="cursor:pointer;">提示词</div>
          </div>
          <div class="center-text-item">
            <img src="../assets/img/icon-clear.png" class="center-clear" />
            <div @click="clearHistory" style="cursor:pointer;">清空记录</div>
          </div>
        </div>
      </div>
      <img
        src="../assets/img/icon-send.png"
        class="right-img"
        @click="sendMessage"
      />
    </div>
    <!-- 图片放大弹窗 -->
    <div v-if="showImgDialog" class="img-dialog-mask" @click="closeImgDialog">
      <div class="img-dialog-ctrl-box" @click.stop @wheel="handleImgWheel">
        <img :src="dialogImgUrl" class="img-dialog-img" :style="{transform: 'scale(' + imgDialogScale + ')'}" />
      </div>
    </div>
    <!-- 预设提示词弹窗 -->
    <div v-if="showTipsList" class="tips-list-mask" @click="showTipsList=false">
      <div class="tips-list-box" @click.stop>
        <div class="tips-list-title">选择提示词</div>
        <div class="tips-list-content tips-list-scroll">
          <div v-for="item in question" :key="item.id" class="tips-list-item" @click="selectTip(item.name)">
            {{ item.name }}
          </div>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
  import Vue from 'vue'
  import { Toast, Loading, Uploader, showToast } from 'vant'
  Vue.use(Toast)
  Vue.use(Loading)
  Vue.use(Uploader)
  import { search } from '../api/index'
  export default {
    data() {
      return {
        // 全部提示词
        question: [
          { name: '该图片中有什么缺陷？', id: 1 },
          { name: '图片中异常产生的原因是什么？', id: 2 },
          { name: '增材制造过程中会发生哪些异常？', id: 3 },
          { name: '图像展示的是铺粉阶段还是打印阶段？', id: 4 },
          { name: '图片中是否存在污染物异常现象？', id: 5 },
          { name: '图像是否显示出铺粉不完全的异常现象？', id: 6 },
          { name: '请分析该图像对应的是增材制造的哪个阶段？', id: 7 },
          { name: '该图像是否呈现出增材制造过程中可能发生的异常特征？', id: 8 },
          { name: '在激光熔融打印增材制造的图像中，可能观察到哪些类型的异常现象？', id: 9 },
          { name: '该图像展示的是增材制造的哪个阶段？', id: 10 },
          { name: '在增材制造的打印阶段，可能检测到哪些异常现象？', id: 11 },
          { name: '导致铺粉不完全异常的因素有哪些？', id: 12 },
          { name: '刮刀横竖条纹缺陷的主要成因有哪些？', id: 13 },
          { name: '导致激光熔融打印过程中球化缺陷的主要因素有哪些？', id: 14 },
          { name: '在增材制造过程中，图片中是否显示出任何异常现象？', id: 15 },
          { name: '在增材制造的打印阶段，可能检测到哪些异常情况？', id: 16 },
          { name: '提供的图像属于激光熔融增材制造的铺粉阶段还是打印阶段？', id: 17 },
          { name: '图片中是否出现了增材制造过程的异常现象？', id: 18 },
          { name: '该图片属于增材制造过程中铺粉阶段还是打印阶段？', id: 19 },
          { name: '在铺粉阶段可能出现哪些典型异常现象？', id: 20 },
          { name: '图片中是否存在翘曲凸起的异常？', id: 21 },
          { name: '在激光熔融打印过程中，导致球化异常现象的潜在成因有哪些？', id: 22 },
          { name: '在激光熔融打印增材制造过程中，可能引发哪些类型的异常现象？', id: 23 },
          { name: '在激光熔融打印过程中，球化现象通常由哪些关键参数或材料特性引发？', id: 24 },
          { name: '激光熔融打印过程包含哪些阶段？', id: 25 },
          { name: '图片中是否存在由热应力引起的翘曲或表面凸起缺陷？', id: 26 },
          { name: '图片中是否存在球化异常？', id: 27 },
          { name: '在增材制造过程中，图片中是否观察到异常现象？', id: 28 },
          { name: '你是什么模型？', id: 29 },
          { name: '你是谁？', id: 30 },
          { name: '在图像中可能观察到哪些增材制造过程的异常现象？', id: 31 },
          { name: '该图片有问题吗？', id: 32 },
          { name: '这个图片有没有缺陷？', id: 33 },
          { name: '图片有什么异常吗？', id: 34 },
        ],
        // 首页当前展示的四个问题
        homeQuestions: [],
        // 问题记录
        history: [],
        // 加载状态
        load: false,
        message: '',
        imageUrl: '',   // 预览图片url
        imageName: '',  // 图片文件名
        fileList: [],
        showImgDialog: false,
        dialogImgUrl: '',
        showTipsList: false,
        likedMessages: new Set(), // 记录已点赞的消息
        imgDialogScale: 1,
        lastMsg: null,
      }
    },
    created() {
      // 默认展示前四个
      this.homeQuestions = this.question.slice(0, 4)
    },
    methods: {
      // 点击发送消息
      sendMessage() {
        if (!this.message) {
          Toast('请输入内容')
          return
        }
        // 发送请求前保存图片和问题
        const question = this.message
        const imageFile = this.fileList.length ? this.fileList[0].file : null
        // 清空输入框和图片预览
        this.message = ''
        this.imageUrl = ''
        this.imageName = ''
        this.fileList = []
        // 展示用户消息
        this.history.push({
          type: 'send',
          message: question,
          from: 'user',
          time: new Date().getTime(),
          reqParams: {
            question,
            imageFile
          }
        })
        this.load = true
        this.$nextTick(() => {
          const chatList = this.$refs.chatList
          if (chatList) {
            chatList.scrollTop = chatList.scrollHeight
          }
        })
        // 构造 formData
        const formData = new FormData()
        formData.append('question', question)
        if (imageFile) formData.append('image', imageFile)
        // 请求接口
        fetch('http://192.168.0.213:6789/analyze/', {
          method: 'POST',
          body: formData
        })
          .then(res => res.json())
          .then(res => {
            this.load = false
            this.history.push({
              type: 'send',
              from: 'system',
              message: res.answer,
              imgArry: [
                res.original_image_url ? res.original_image_url : '',
                res.yolo_output_image_url ? res.yolo_output_image_url : ''
              ].filter(Boolean),
              time: new Date().getTime(),
              reqParams: {
                question,
                imageFile
              }
            })
            this.lastMsg = this.history[this.history.length - 1]
            this.$nextTick(() => {
              const sysMsg = this.$refs['system-' + this.history[this.history.length - 1].time]
              if (sysMsg && sysMsg[0]) {
                const top = sysMsg[0].getBoundingClientRect().top + window.pageYOffset
                window.scrollTo({
                  top: top - 200,
                  behavior: 'smooth'
                })
              }
            })
          })
          .catch(() => {
            this.load = false
            Toast('请求失败')
          })
      },
      setMessage(name) {
        this.message = name
      },
      onAfterRead(file) {
        this.imageUrl = file.content
        this.imageName = file.file.name
        this.fileList = [file] // 只保留当前上传的图片
      },
      getFullImgUrl(path, type) {
        if (!path) return ''
        if (path.startsWith('http')) return path
        if (type === 'original') {
          return 'http://192.168.0.213:6789/' + path.replace(/^\/?/, '')
        } else if (type === 'yolo') {
          return 'http://192.168.0.213:6789' + (path.startsWith('/') ? path : '/' + path)
        }
        return path
      },
      handleImgClick(url) {
        this.dialogImgUrl = url
        this.showImgDialog = true
      },
      closeImgDialog() {
        this.showImgDialog = false
        this.dialogImgUrl = ''
        this.imgDialogScale = 1
      },
      openTipsList() {
        this.showTipsList = true
      },
      selectTip(tip) {
        this.message = tip
        this.showTipsList = false
      },
      clearHistory() {
        this.history = []
      },
      formatMessage(msg) {
        if (!msg) return ''
        return msg.replace(/\n/g, '<br>')
      },
      async handleRefresh(item) {
        // 重新请求当前问题（带图片参数），用历史记录的reqParams
        const { reqParams } = item
        if (!reqParams) return
        const { question, imageFile } = reqParams
        // 移除当前system回答（即item）在history中的那一项
        const idx = this.history.indexOf(item)
        if (idx !== -1) this.history.splice(idx, 1)
        this.load = true
        const formData = new FormData()
        formData.append('question', question)
        if (imageFile) formData.append('image', imageFile)
        fetch('http://192.168.0.213:6789/analyze/', {
          method: 'POST',
          body: formData
        })
          .then(res => res.json())
          .then(res => {
          this.load = false
          this.history.push({
            type: 'send',
            from: 'system',
              message: res.answer,
              imgArry: [
                res.original_image_url ? res.original_image_url : '',
                res.yolo_output_image_url ? res.yolo_output_image_url : ''
              ].filter(Boolean),
            time: new Date().getTime(),
              reqParams: {
                question,
                imageFile
              }
            })
            this.lastMsg = this.history[this.history.length - 1]
            this.$nextTick(() => {
              const sysMsg = this.$refs['system-' + this.history[this.history.length - 1].time]
              if (sysMsg && sysMsg[0]) {
                const top = sysMsg[0].getBoundingClientRect().top + window.pageYOffset
                window.scrollTo({
                  top: top - 200,
                  behavior: 'smooth'
                })
              }
            })
          })
          .catch(() => {
            this.load = false
            Toast('请求失败')
          })
      },
      handleCopy(text) {
        if (!text) return
        if (navigator.clipboard) {
          navigator.clipboard.writeText(text)
          Toast('已复制')
        } else {
          // 兼容性处理
          const textarea = document.createElement('textarea')
          textarea.value = text
          document.body.appendChild(textarea)
          textarea.select()
          document.execCommand('copy')
          document.body.removeChild(textarea)
          Toast('已复制')
        }
      },
      refreshQuestions() {
        // 随机抽取4个不重复的问题
        let arr = [...this.question]
        // 保证每次都不和当前homeQuestions完全一样
        let newArr = []
        while (newArr.length < 4 && arr.length) {
          const idx = Math.floor(Math.random() * arr.length)
          const q = arr.splice(idx, 1)[0]
          if (!this.homeQuestions.find(hq => hq.id === q.id)) {
            newArr.push(q)
          }
        }
        // 如果不够4个，补齐
        while (newArr.length < 4) {
          const idx = Math.floor(Math.random() * this.question.length)
          const q = this.question[idx]
          if (!newArr.find(nq => nq.id === q.id)) {
            newArr.push(q)
          }
        }
        this.homeQuestions = newArr
      },
      handleLike(time) {
        if (this.likedMessages.has(time)) {
          this.likedMessages.delete(time)
          Toast('取消点赞')
        } else {
          this.likedMessages.add(time)
          Toast('点赞成功')
        }
      },
      handleVoice(text) {
        if (!text) return
        // 使用浏览器原生语音合成API
        if ('speechSynthesis' in window) {
          // 停止当前播放
          window.speechSynthesis.cancel()
          const utterance = new SpeechSynthesisUtterance(text)
          utterance.lang = 'zh-CN'
          utterance.rate = 1
          utterance.pitch = 1
          utterance.volume = 1
          window.speechSynthesis.speak(utterance)
          Toast('开始播放语音')
        } else {
          Toast('浏览器不支持语音播放')
        }
      },
      handleImgWheel(e) {
        if (e.ctrlKey) {
          e.preventDefault()
          let factor = e.deltaY < 0 ? 1.1 : 0.9
          let next = this.imgDialogScale * factor
          if (next < 0.2) next = 0.2
          if (next > 5) next = 5
          this.imgDialogScale = next
        }
      },
    },
  }
</script>

