import Vue from 'vue'
import VueRouter from 'vue-router'
import lauya from '@/views/index.vue'
Vue.use(VueRouter)

const routes = [
  {
    //一级路由
    path: '/',
    name: 'lauya',
    component: lauya,
  },
  {
    //404页面
    //假如路由出错可以跳转404
    path:"*",
    component: () => import( '../views/Errone.vue')
  },
]

const router = new VueRouter({
  mode: 'history',
  base: process.env.BASE_URL,
  routes
})

export default router
